DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:MIX 054", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "d491ac95-5f48-5630-ae26-1f7a2eb1e17c", "stem": "Which graph shows profit increasing at a constant positive rate over time?", "choices": [{"key": "A", "text": "Graph A"}, {"key": "B", "text": "Graph B"}, {"key": "C", "text": "Graph C"}, {"key": "D", "text": "Graph D"}], "type": "mcq", "correct": "A", "explanation": "A is a straight line with positive slope, so equal increases in time give equal positive increases in profit. B decreases, C is constant, and D increases at a changing rate.", "topic": "Functions, Transformations & Graphs", "note": "Clarified “steady increase” as a constant positive rate and preserved all graph choices.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 448, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "parts": [{"label": "Q8", "question_id": "d410629b-9cc5-5891-8613-45d475d6425e", "stem": "Which listed values solve \\(\\sqrt{x+2}=x\\)? I. 0; II. 2; III. −1.", "choices": [{"key": "A", "text": "I only"}, {"key": "B", "text": "II only"}, {"key": "C", "text": "II and III only"}, {"key": "D", "text": "I, II, and III"}], "type": "mcq", "correct": "B", "explanation": "The nonnegative square root requires x≥0. Squaring gives x²−x−2=(x−2)(x+1)=0. Candidate 2 works; −1 is extraneous because √1=1≠−1. Also x=0 fails. Only II solves the original equation.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:MIX 055", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "cfa6949c-0737-572b-a744-1f243f9150fc", "stem": "What value of x satisfies \\(4^{2x-1}=256\\)?", "choices": [{"key": "A", "text": "3.5"}, {"key": "B", "text": "4"}, {"key": "C", "text": "1.5"}, {"key": "D", "text": "2.5"}], "type": "mcq", "correct": "D", "explanation": "Since 256=4⁴, equality of powers with base 4 gives 2x−1=4. Therefore x=5/2=2.5.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Recovered the full exponent 2x−1. Split the preceding graph-choice question as Q8.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 449, "extra_sources": [], "parts": [{"label": "Q8", "question_id": "3a5bb92e-ed5f-5eff-b2e5-1f9cc5475a80", "stem": "Which displayed graph represents both f(x)=3x+1 and g(x)=2x−1?", "choices": [{"key": "A", "text": "Graph A"}, {"key": "B", "text": "Graph B"}, {"key": "C", "text": "Graph C"}, {"key": "D", "text": "Graph D"}], "type": "mcq", "correct": "B", "explanation": "The y-intercepts must be 1 and −1 and both slopes positive, with f steeper. Their intersection satisfies 3x+1=2x−1, so x=−2 and y=−5. Graph B has these intercepts and intersection; the others do not.", "topic": "Functions, Transformations & Graphs", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified.", "assets": {"figure": "data:image/jpeg;base64,"}}]}, {"id": "clean:MIX 056", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Exact repeated complex-number question. Both originals checked; (2i−1)/(i−4)+3i−1=(44i−11)/17, C. Reused MIX 041.", "correct": "C", "question_id": "351fa76b-61f0-57c1-ac7c-dcbf350f49f1", "duplicate_of": "clean:MIX 041"}, {"id": "clean:MIX 057", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Exact repeated function question. h(3)=5 gives a=−1 and h(1)=1, A. Reused MIX 042.", "correct": "A", "question_id": "fa15f2ab-d30e-51c8-8a6f-63aa5af75c2a", "duplicate_of": "clean:MIX 042"}, {"id": "clean:MIX 058", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "f012ab91-4525-535c-b2a7-65c4bfdcf10d", "stem": "A quadratic graph has vertex (−2,−3) and passes through (0,1). Which equation represents it?", "choices": [{"key": "A", "text": "f(x)=x²−4x+1"}, {"key": "B", "text": "f(x)=x²+4x+1"}, {"key": "C", "text": "f(x)=x²−4x−1"}, {"key": "D", "text": "f(x)=x²+4x−1"}], "type": "mcq", "correct": "B", "explanation": "Vertex form gives f(x)=a(x+2)²−3. At (0,1), 1=4a−3, so a=1. Expanding yields f(x)=x²+4x+1.", "topic": "Functions, Transformations & Graphs", "note": "Read the vertex and y-intercept from the source graph and transcribed them explicitly; the watermark does not obscure those two determining features.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 451, "extra_sources": [], "parts": [{"label": "Q33", "question_id": "eb0dc586-24c5-5b58-8d7f-0e745430090a", "stem": "If P(x)=10x³−mx²−10x+3 is divisible by 2x+1, what is m?", "choices": [{"key": "A", "text": "12"}, {"key": "B", "text": "17"}, {"key": "C", "text": "27"}, {"key": "D", "text": "32"}], "type": "mcq", "correct": "C", "explanation": "The divisor has root x=−1/2. The factor theorem gives P(−1/2)=−5/4−m/4+5+3=(27−m)/4=0. Thus m=27.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:MIX 060", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "2e67b135-bad3-598e-a20d-0656ac07a55a", "stem": "Twenty-two percent of what number is 88?", "choices": [{"key": "A", "text": "400"}, {"key": "B", "text": "320"}, {"key": "C", "text": "50"}, {"key": "D", "text": "120"}], "type": "mcq", "correct": "A", "explanation": "Solve 0.22n=88: n=88/0.22=400. Check: 22% of 400 is 88.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split the complete questions in the shared crop. Q36 has a missing exponent numerator and no integer constraints; Q39 lacks a clear equation/graph target. Those two fragments remain excluded.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 453, "extra_sources": [], "parts": [{"label": "Q38", "question_id": "5a9ac75f-b524-5b65-9311-b1fbb278f203", "stem": "If 2r+4q=18 and r+2q=g+17, what is g?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "5"}, {"key": "C", "text": "11"}, {"key": "D", "text": "−8"}], "type": "mcq", "correct": "D", "explanation": "Divide the first equation by 2 to obtain r+2q=9. Thus g+17=9 and g=−8.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}, {"label": "Q40", "question_id": "cb0a69af-1c40-527e-818d-01a5122f8b05", "stem": "A discounted smart watch and a smart pen cost $377 together. The pen costs $88. If the watch is discounted by 15%, what was its original price?", "choices": [{"key": "A", "text": "$300"}, {"key": "B", "text": "$320"}, {"key": "C", "text": "$340"}, {"key": "D", "text": "$440"}], "type": "mcq", "correct": "C", "explanation": "The discounted watch costs 377−88=$289, which is 85% of its original price. Therefore its original price is 289/0.85=$340.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}, {"label": "Q41", "question_id": "cf10fd73-53b4-5d8c-ac41-13bdfc6b1859", "stem": "Using the median of the upper half, what is the upper quartile of 4,4,5,7,8,9,10,20,20,21,24,25?", "choices": [{"key": "A", "text": "15"}, {"key": "B", "text": "20"}, {"key": "C", "text": "20.5"}, {"key": "D", "text": "21"}], "type": "mcq", "correct": "C", "explanation": "The upper half is 10,20,20,21,24,25. Its median is the mean of its third and fourth terms: (20+21)/2=20.5.", "topic": "Statistics, Probability & Data Analysis", "note": "Stated the quartile convention explicitly to avoid conflicting interpolation definitions."}]}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
